CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY,username TEXT NOT NULL UNIQUE,email TEXT UNIQUE,password TEXT, rating INTEGER NOT NULL DEFAULT 1200,bio TEXT NOT NULL DEFAULT '',joined TEXT NOT NULL,wallet TEXT UNIQUE);
CREATE TABLE IF NOT EXISTS sessions(token TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,expires BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS games(id TEXT PRIMARY KEY,state JSONB NOT NULL,rated_applied BOOLEAN NOT NULL DEFAULT false);
CREATE TABLE IF NOT EXISTS nonces(nonce TEXT PRIMARY KEY,expires BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS reset_tokens(token TEXT PRIMARY KEY,user_id TEXT REFERENCES users(id),expires BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS audit(id BIGSERIAL PRIMARY KEY,user_id TEXT,action TEXT NOT NULL,created TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX IF NOT EXISTS session_expiry ON sessions(expires);
CREATE INDEX IF NOT EXISTS games_status ON games((state->>'status'));
